package com.dataengine.governance.service;
import com.dataengine.governance.api.GovernanceReportResponse; import com.dataengine.governance.domain.*; import com.dataengine.governance.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
@Service @Transactional(readOnly=true) public class GovernanceReportService {private final DataChangeRepository changes;private final ApprovalTaskRepository approvals;private final DataContractRepository contracts;private final QualityResultRepository quality;private final LineageEdgeRepository lineage;public GovernanceReportService(DataChangeRepository c,ApprovalTaskRepository a,DataContractRepository d,QualityResultRepository q,LineageEdgeRepository l){changes=c;approvals=a;contracts=d;quality=q;lineage=l;}public GovernanceReportResponse overview(){var all=changes.findAll();Map<String,Long> risk=all.stream().collect(Collectors.groupingBy(x->x.getRiskLevel().name(),Collectors.counting()));Map<String,Long> status=all.stream().collect(Collectors.groupingBy(x->x.getStatus().name(),Collectors.counting()));long waiting=all.stream().filter(x->x.getStatus()==ChangeStatus.WAITING_APPROVAL).count();long blocked=all.stream().filter(x->x.getContractGate()==GateStatus.BLOCK||x.getQualityGate()==GateStatus.BLOCK).count();long active=contracts.findAll().stream().filter(x->x.getStatus()==ContractStatus.ACTIVE).count();long draft=contracts.findAll().stream().filter(x->x.getStatus()==ContractStatus.DRAFT).count();long open=quality.findAll().stream().filter(x->Set.of(QualityResultStatus.OPEN,QualityResultStatus.ACKNOWLEDGED).contains(x.getStatus())).count();long confirmed=lineage.findAll().stream().filter(x->x.getStatus()==LineageStatus.CONFIRMED).count();long candidate=lineage.findAll().stream().filter(x->x.getStatus()==LineageStatus.CANDIDATE).count();return new GovernanceReportResponse(all.size(),waiting,blocked,active,draft,open,confirmed,candidate,risk,status);}}
